qs_goal_solution() {
  case "$1" in
    'where')
      printf '%s\n' 'pwd'
      ;;
    'look')
      printf '%s\n' 'ls'
      ;;
    'welcome')
      printf '%s\n' 'cat welcome.txt'
      ;;
    'cottage')
      printf '%s\n' 'cd cottage'
      ;;
    'diary')
      printf '%s\n' 'cd bedroom'
      printf '%s\n' 'cat diary.txt'
      ;;
    'compass')
      printf '%s\n' 'cd drawer'
      printf '%s\n' 'cat brass-compass.txt'
      ;;
    'matches')
      printf '%s\n' 'cd ../../kitchen/cupboard'
      printf '%s\n' 'cat matches.txt'
      ;;
    'pearl')
      printf '%s\n' 'cd ~/lighthouse/shore'
      printf '%s\n' 'ls -a'
      printf '%s\n' 'cat .crab-shell/pearl.txt'
      ;;
    'climb')
      printf '%s\n' 'cd ../tower/stairs/landing/lantern-room'
      ;;
    'history')
      printf '%s\n' 'history'
      ;;
    'lamp')
      printf '%s\n' 'cat lamp.txt'
      ;;
  esac
}

